export const getGetRecognitionRecommendationsUrl = (params: GetRecognitionRecommendationsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/firm/recognition/recommendations?${stringifiedParams}` : `/api/firm/recognition/recommendations`
}

